const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let project={title:'',territory:'',goal:'',people:'',resources:'',calendar:'',indicator:'',method:'',funding:'',fundingSource:'',contact:'',email:'',consent:false,lines:[{label:'',qty:'',unit:'',source:''}]},step=0;
const euro=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(n);
export function openReport(root,recipient,seedResources=''){
 if(seedResources&&!project.resources.includes(seedResources))project.resources+=(project.resources?'

':'')+'Acteurs repérés — relation non confirmée :
'+seedResources;
 const titles=['Donner un cadre.','Décrire les moyens.','Documenter le budget.','Prévoir le suivi.','Le dossier de mobilisation.'];
 const field=(key,label,attrs='',area=false)=>`<label>${label}${area?`<textarea name="${key}" maxlength="${key==='resources'?5000:900}" ${attrs}>${esc(project[key])}</textarea>`:`<input name="${key}" value="${esc(project[key])}" maxlength="180" ${attrs}>`}</label>`;
 const calc=()=>{const lines=project.lines.filter(l=>[l.label,l.qty,l.unit,l.source].some(x=>String(x).trim()));const complete=lines.length>0&&lines.every(l=>l.label.trim()&&l.qty!==''&&Number.isFinite(Number(l.qty))&&Number(l.qty)>0&&l.unit!==''&&Number.isFinite(Number(l.unit))&&Number(l.unit)>=0);const total=complete?lines.reduce((sum,l)=>sum+Number(l.qty)*Number(l.unit),0):null;const funds=project.funding!==''&&Number.isFinite(Number(project.funding))&&Number(project.funding)>=0?Number(project.funding):null;return{lines,complete,total,funds,gap:total!==null&&funds!==null?Math.max(0,total-funds):null}};
 function report(){const c=calc();return `OANA — DOSSIER DE PROJET / DOCUMENT DE TRAVAIL
${project.title||'Projet à nommer'}
Établi le ${new Date().toLocaleDateString('fr-FR')}

1. LE BESOIN ET L’OBJECTIF
Territoire : ${project.territory||'À documenter'}
Objectif : ${project.goal||'À documenter'}
Bénéficiaires : ${project.people||'À documenter'}

2. MOYENS ET CALENDRIER
Ressources : ${project.resources||'À documenter'}
Étapes et échéances : ${project.calendar||'À documenter'}

3. BUDGET PRÉVISIONNEL
`+c.lines.map((l,i)=>`${i+1}. ${l.label||'Poste à nommer'} : ${l.qty||'Quantité à documenter'} × ${l.unit!==''?euro(Number(l.unit)):'Montant unitaire à documenter'}${l.qty!==''&&l.unit!==''?' = '+euro(Number(l.qty)*Number(l.unit)):''}
Source / hypothèse : ${l.source||'À documenter'}`).join('

')+`

Total prévisionnel : ${c.total===null?'À compléter : toutes les lignes doivent être renseignées.':euro(c.total)}
Fonds reçus déclarés : ${c.funds===null?'Non renseignés':euro(c.funds)}
Source des fonds déclarés : ${project.fundingSource||'À documenter'}
Solde prévisionnel à mobiliser : ${c.gap===null?'À calculer après renseignement du budget et des fonds reçus.':euro(c.gap)}

Les montants sont saisis par le porteur du dossier. Les justificatifs ne sont ni transmis ni vérifiés par cet outil. Le budget ne constitue pas une campagne validée ou un appel aux dons publié.

4. SUIVI ET COMPTE RENDU
Indicateur attendu : ${project.indicator||'À documenter'}
Méthode et preuves de suivi : ${project.method||'À documenter'}
Le rapport de réalisation devra renseigner : actions réalisées ; écarts avec le calendrier ; dépenses réelles et justificatifs ; fonds reçus ; bénéficiaires effectivement touchés ; résultats mesurés ; enseignements et suites. Ces résultats ne sont pas préremplis.

5. PORTEUR ET TRANSMISSION
Contact : ${project.contact||'À compléter'}
Email : ${project.email||'À compléter'}
Destination : ${recipient}

Projet proposé à OANA pour étude, sans publication, collecte ou engagement automatique.`}
 function save(){const form=root.querySelector('form');if(!form)return;const v=Object.fromEntries(new FormData(form));for(const [k,val]of Object.entries(v))if(!k.startsWith('line-'))project[k]=String(val).trim();if(step===3)project.consent=v.consent==='on';if(step===2)project.lines=project.lines.map((l,i)=>({label:String(v['line-label-'+i]||'').trim(),qty:String(v['line-qty-'+i]||''),unit:String(v['line-unit-'+i]||''),source:String(v['line-source-'+i]||'').trim()}));}
 function download(kind='txt'){const c=kind==='json'?JSON.stringify({type:'dossier-projet-oana',version:1,date:new Date().toISOString(),...project,calculation:calc(),status:'À étudier — aucune collecte automatique'},null,2):report();const u=URL.createObjectURL(new Blob([c],{type:kind==='json'?'application/json':'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='OANA-dossier-projet.'+kind;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
 function draw(){let body='';if(step===0)body=field('title','Nom du projet','required')+field('territory','Commune / territoire concerné','required')+field('goal','Quel besoin et quel changement recherché ?','required',true)+field('people','Pour qui ? Combien de personnes si cette estimation existe ?','required',true);
 if(step===1)body=field('resources','Moyens humains, lieux, équipements et appuis nécessaires','required',true)+field('calendar','Les étapes et les échéances envisagées','required',true);
 if(step===2)body=`<p class="notice">Renseignez les postes connus. Laissez un montant vide si vous ne le connaissez pas : aucun total complet ne sera annoncé. Chaque source peut être un devis, une référence ou une hypothèse explicitée.</p><div class="budget-lines">${project.lines.map((l,i)=>`<fieldset><legend>Poste ${i+1}</legend><label>Intitulé<input name="line-label-${i}" value="${esc(l.label)}" maxlength="140"></label><div class="budget-numbers"><label>Quantité<input name="line-qty-${i}" type="number" min="0.01" step="0.01" value="${esc(l.qty)}"></label><label>Montant unitaire prévu (€)<input name="line-unit-${i}" type="number" min="0" step="0.01" value="${esc(l.unit)}"></label></div><label>Source / hypothèse<input name="line-source-${i}" value="${esc(l.source)}" maxlength="250" placeholder="Référence de devis, hypothèse à vérifier…"></label>${project.lines.length>1?`<button type="button" class="budget-remove" data-remove="${i}">Retirer ce poste</button>`:''}</fieldset>`).join('')}</div><button type="button" class="secondary" id="add-line">Ajouter un poste</button><div id="budget-total" class="budget-total" aria-live="polite"></div>`+field('funding','Fonds déjà reçus déclarés (€), si connus','type="number" min="0" step="0.01"')+field('fundingSource','Source / référence permettant de justifier ces fonds','');
 if(step===3)body=field('indicator','Quel résultat souhaitez-vous pouvoir mesurer ?','required',true)+field('method','Comment le vérifier ? Qui suivra le projet et avec quelles pièces ?','required',true)+field('contact','Nom du porteur du dossier','required autocomplete="name"')+field('email','Email du porteur','required type="email" autocomplete="email"')+`<label class="consent"><input name="consent" type="checkbox" ${project.consent?'checked':''} required><span>J’accepte de préparer ce dossier pour son étude par OANA. Je vérifierai les éléments avant de l’envoyer.</span></label>`;
 if(step===4)body=`<div class="contribution-review">${esc(report())}</div><div class="dialog-actions"><button type="button" class="primary" id="report-mail">Préparer l’email</button><button type="button" class="secondary" id="report-download">Rapport texte</button><button type="button" class="secondary" id="report-json">Données du dossier</button></div><p class="notice">Le dossier est préparé dans cette page, sans mise en ligne des réponses. OANA pourra l’étudier avant de présenter un projet ou d’organiser une collecte. Le suivi réel et ses justificatifs seront ajoutés par l’association.</p>`;
 root.innerHTML=`<span class="eyebrow">DOSSIER DE PROJET · ${step+1} / 5</span><div class="vote-progress"><i style="width:${step/4*100}%"></i></div><h2 id="content-title" tabindex="-1">${titles[step]}</h2><form id="report-form"><div class="vote-fields">${body}</div><p class="vote-status" role="status"></p><div class="vote-nav"><button type="button" class="secondary" id="report-back">${step?'Précédent':'Les dossiers'}</button>${step<4?'<button class="primary" type="submit">Continuer</button>':'<button class="secondary" type="button" id="report-new">Nouveau dossier</button>'}</div></form>`;
 const total=()=>{const el=root.querySelector('#budget-total');if(!el)return;const c=calc();el.textContent=c.total===null?'Budget incomplet : complétez les quantités et montants pour calculer le total.':'Total prévisionnel : '+euro(c.total)};
 root.querySelector('form').onsubmit=e=>{e.preventDefault();if(!e.target.reportValidity())return;save();if(step===2&&project.funding!==''&&!project.fundingSource){root.querySelector('.vote-status').textContent='Indiquez la source des fonds reçus déclarés, ou laissez le montant vide.';return}step=Math.min(4,step+1);draw();root.closest('dialog').scrollTop=0;root.querySelector('h2').focus({preventScroll:true})};
 root.querySelector('#report-back').onclick=()=>{save();if(step){step--;draw();root.closest('dialog').scrollTop=0}else document.dispatchEvent(new Event('oana-projects'))};
 root.querySelector('#add-line')?.addEventListener('click',()=>{save();if(project.lines.length>=15){root.querySelector('.vote-status').textContent='Le dossier accepte jusqu’à 15 postes.';return}project.lines.push({label:'',qty:'',unit:'',source:''});draw()});
 root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{save();project.lines.splice(Number(b.dataset.remove),1);draw()});
 root.querySelector('#report-form').addEventListener('input',()=>{save();total()});total();
 root.querySelector('#report-download')?.addEventListener('click',()=>download());root.querySelector('#report-json')?.addEventListener('click',()=>download('json'));
 root.querySelector('#report-mail')?.addEventListener('click',()=>{const full=report(),long=encodeURIComponent(full).length>1600,body=long?`Bonjour OANA,

Je vous propose le projet « ${project.title} ». Le dossier complet OANA-dossier-projet.txt est à joindre à ce message.

${project.contact}
${project.email}`:full;root.querySelector('.vote-status').innerHTML=`<a class="primary" href="mailto:${recipient}?subject=${encodeURIComponent('OANA — Dossier de projet : '+project.title)}&body=${encodeURIComponent(body)}">Ouvrir ma messagerie</a><p class="notice">${long?'Téléchargez le rapport et joignez-le à votre email. ':''}Vérifiez votre message avant de l’envoyer. Aucune collecte de fonds n’est lancée par cette action.</p>`});
 root.querySelector('#report-new')?.addEventListener('click',()=>{project={title:'',territory:'',goal:'',people:'',resources:'',calendar:'',indicator:'',method:'',funding:'',fundingSource:'',contact:'',email:'',consent:false,lines:[{label:'',qty:'',unit:'',source:''}]};step=0;draw()});
 }
 draw();
}

