import {openObservatory,candidates} from '/oana/observatoire.js';
import {openPlaces} from '/oana/lieux.js';
import {openReport} from '/oana/project-report.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Public content is limited to the association's existing MaisonWRLD presentation.
const recipient='oasisnancee@gmail.com';
const axes=[{"id": "culture", "title": "Accéder à la création", "intro": "Pratiquer la musique, le son et l’image dans des lieux d’accueil existants.", "purpose": "Construire des parcours de découverte et de création avec les publics et les équipes d’accueil.", "people": "Habitants, groupes accompagnés, artistes et lieux d’accueil.", "needs": "Accès, horaires, intervenants, matériel et conditions d’accueil."}, {"id": "soutien", "title": "Faire aboutir les projets", "intro": "Passer d’une envie à un projet réalisable.", "purpose": "Clarifier les étapes, réunir les compétences et orienter vers les ressources adaptées.", "people": "Créateurs, collectifs, associations et structures.", "needs": "Diagnostic, calendrier, devis, responsabilités et ressources confirmées."}, {"id": "territoire", "title": "Créer avec le territoire", "intro": "Des récits sonores et audiovisuels conçus avec les habitants.", "purpose": "Relier les mémoires, les expressions contemporaines et les lieux de vie.", "people": "Habitants, artistes, lieux culturels et acteurs de proximité.", "needs": "Écoute, coconstruction, autorisations et restitution accessible."}];
const rooms={parvis:{number:'LE PARVIS',title:'Une maison<br>commune.',desc:'Un lieu pour relier les idées,<br>les personnes et le territoire.',actions:[['nef','Entrer dans l’institution']]},nef:{number:'01 / LA NEF',title:'La place<br>des possibles.',desc:'Choisissez un espace. Explorez un dossier, participez ou faites entendre un besoin.',actions:[['projets','Découvrir les dossiers'],['open:lieux','Les lieux & coopérations'],['open:reseau','Trouver une ressource'],['open:observatoire','L’observatoire']]},projets:{number:'02 / LES DOSSIERS',title:'Des idées.<br>Un territoire.',desc:'Les axes de travail d’OANA, réunis dans une galerie à explorer.',actions:[['open:projets','Ouvrir les dossiers']]},urne:{number:'03 / L’URNE',title:'Votre voix<br>a sa place.',desc:'Quelles priorités pour la culture et la création sur le territoire ?',actions:[['open:consultation','Participer à la consultation']]},besoins:{number:'04 / LES BESOINS',title:'Ce qui manque.<br>Ce qui peut naître.',desc:'Un lieu, une rencontre, un appui. Décrivez une attente à faire remonter à OANA.',actions:[['open:besoin','Exprimer un besoin']]},agora:{number:'05 / L’AGORA',title:'Faire<br>lien.',desc:'Culture, création et territoire en Normandie : découvrir l’intention de l’association.',actions:[['open:mission','Découvrir OANA']]}};
let room='parvis',architecture=null,paused=false,simple=false,audio=null,sound=false,contribution={mode:'consultation',answers:{},index:0},lastFocus=null;
const plan=$('#plan-dialog'),content=$('#content-dialog');
function dialogOpen(d){lastFocus=document.activeElement;if(!d.open)d.showModal()}
function closeDialog(d){d.close();lastFocus?.focus?.({preventScroll:true})}
for(const d of [plan,content]){d.querySelector('.close').addEventListener('click',()=>closeDialog(d));d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d)}})}
function navigate(name,push=true){if(!rooms[name])return;room=name;const r=rooms[name];$('#room-number').textContent='OANA / '+r.number;$('#room-title').innerHTML=r.title.replaceAll('<br>','<br> ');$('#room-description').innerHTML=r.desc;$('.room-copy').classList.toggle('entered',name!=='parvis');$('#room-actions').innerHTML=r.actions.map(([dest,label])=>`<button class="${(dest.startsWith('open:')||dest==='nef')?'primary':'secondary'}" data-dest="${dest}">${label}${dest==='nef'?'<span class="door-icon" aria-hidden="true"></span>':''}</button>`).join('');$('#room-actions').querySelectorAll('button').forEach(b=>b.onclick=()=>b.dataset.dest.startsWith('open:')?openContent(b.dataset.dest.slice(5)):navigate(b.dataset.dest));if(simple&&name==='parvis')$('#room-actions').innerHTML=Object.entries(rooms).filter(([id])=>id!=='parvis').map(([id,r])=>`<button class="secondary" data-room="${id}">${r.number.split('/ ').pop()}</button>`).join('');bindRoomButtons($('#room-actions'));architecture?.navigate(name);if(push)history.pushState({room:name},'','#'+name);if(plan.open)plan.close();$('#world-status').textContent=simple?'Parcours accessible sans 3D.':'Architecture virtuelle · OANA';}
function bindRoomButtons(node){node.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>navigate(b.dataset.room))}
bindRoomButtons(plan);$('#plan-open').onclick=()=>dialogOpen(plan);addEventListener('popstate',()=>{if(content.open)content.close();navigate(location.hash.slice(1)||'parvis',false)});
const spotNames={projets:'Les dossiers',urne:'L’urne',besoins:'Les besoins',agora:'L’agora'};for(const [id,label]of Object.entries(spotNames)){const b=document.createElement('button');b.className='hotspot';b.dataset.room=id;b.textContent=label;b.hidden=true;b.onclick=()=>room===id?openContent(id==='urne'?'consultation':id==='besoins'?'besoin':id==='agora'?'mission':'projets'):navigate(id);$('#hotspots').append(b)}
function projectList(){return `<span class="eyebrow">GALERIE DES DOSSIERS</span><h2 id="content-title">Les champs d’action.</h2><p>Trois axes pour commencer à l’échelle du terrain. Les projets se construisent avec les publics et les lieux existants ; chaque engagement reste à confirmer.</p><div class="dossier-list">${axes.map(a=>`<button class="dossier-card" data-axis="${a.id}"><span class="folder-symbol" aria-hidden="true"></span><strong>${a.title}</strong><small>Dossier-cadre / explorer</small></button>`).join('')}</div><div class="project-create"><p>Transformer une attente en projet, documenter les moyens et préparer la mobilisation.</p><button class="primary" id="project-create">Préparer un dossier de projet</button></div>`}
function projectDetail(id){const a=axes.find(a=>a.id===id);if(!a)return;$('#content-body').innerHTML=`<span class="eyebrow">DOSSIER-CADRE / OANA</span><h2 id="content-title">${a.title}</h2><p>${a.intro}</p><div class="detail-lines"><div><span>L’intention</span><strong>${a.purpose}</strong></div><div><span>Les personnes concernées</span><strong>${a.people}</strong></div><div><span>Les besoins à explorer</span><strong>${a.needs}</strong></div></div><p class="notice">Cet axe présente un champ d’action. Il ne décrit pas un projet réalisé, financé ou ouvert aux inscriptions.</p><div class="dialog-actions"><button class="primary" id="axis-need">Exprimer un besoin lié</button><button class="secondary" id="axis-data">Consulter les données</button><button class="secondary" id="axis-back">Les autres dossiers</button></div>`;$('#axis-data').onclick=()=>openContent('observatoire');$('#axis-back').onclick=()=>openContent('projets');$('#axis-need').onclick=()=>{contribution={mode:'besoin',index:0,answers:{theme:id}};openContent('besoin',true)}}
function openContent(kind,preserve=false){if(kind==='consultation'||kind==='besoin'){if(!preserve&&contribution.mode!==kind)contribution={mode:kind,index:0,answers:{}};renderContribution()}else if(kind==='privacy'){$('#content-body').innerHTML=`<span class="eyebrow">VOS DONNÉES</span><h2 id="content-title">Vous gardez la main.</h2><p>Les réponses aux formulaires restent dans la mémoire de cette page. Elles ne sont pas déposées dans une base collective. Recharger ou fermer la page peut les effacer.</p><p>Le téléchargement crée un fichier sur votre appareil. L’ouverture de la messagerie prépare un email ; vous vérifiez son contenu et décidez de l’envoyer à oasisnancee@gmail.com.</p><p>Le répertoire interroge l’API publique Recherche d’entreprises : le nom recherché, les filtres et votre adresse IP sont transmis à ce service. Ne saisissez pas de donnée confidentielle dans la recherche.</p><p>Le contrôle des appels utilise des sources publiques sans vos réponses personnelles. L’hébergement traite les données techniques nécessaires à la fourniture du site selon ses propres conditions.</p><p>Aucun document interne n’est intégré à cette page publique. Aucune réponse de formulaire n’est envoyée à une IA. Le site ne demande ni caméra ni microphone pour la visite.</p>`}else if(kind==='lieux'){openPlaces($('#content-body'),()=>openContent('report'))}else if(kind==='reseau'){openObservatory($('#content-body'),'acteurs')}else if(kind==='observatoire'){openObservatory($('#content-body'))}else if(kind==='report'){openReport($('#content-body'),recipient,[...candidates.values()].map(x=>x.name+' — '+x.city+' — SIREN '+x.siren).join('\n'))}else if(kind==='projets'){$('#content-body').innerHTML=projectList();$('#content-body').querySelectorAll('[data-axis]').forEach(b=>b.onclick=()=>projectDetail(b.dataset.axis));$('#project-create').onclick=()=>{openReport($('#content-body'),recipient,[...candidates.values()].map(x=>x.name+' — '+x.city+' — SIREN '+x.siren).join('\n'));content.scrollTop=0}}else{$('#content-body').innerHTML=`<span class="eyebrow">L’AGORA / OANA</span><h2 id="content-title">Culture & territoire.</h2><p>OANA — Oasis Nancee — relie les habitants, les créateurs et les ressources du territoire normand, autour de la musique, du son et de l’image.</p><div class="detail-lines"><div><span>Relier</span><strong>Les publics, les créateurs et les structures.</strong></div><div><span>Écouter</span><strong>Les attentes, les freins et les initiatives du territoire.</strong></div><div><span>Construire</span><strong>Des projets accueillis dans des lieux existants, puis évalués avant de changer d’échelle.</strong></div></div><div class="dialog-actions"><button class="primary" id="mission-needs">Faire entendre un besoin</button><button class="secondary" id="mission-folders">Explorer les dossiers</button><button class="secondary" id="mission-places">Les lieux & coopérations</button></div>`;$('#mission-places').onclick=()=>openContent('lieux');$('#mission-needs').onclick=()=>openContent('besoin');$('#mission-folders').onclick=()=>openContent('projets')};dialogOpen(content);content.scrollTop=0;}
document.addEventListener('oana-cooperation',()=>openContent('lieux'));
document.addEventListener('oana-projects',()=>openContent('projets'));
const icons={culture:'<path d="m5 7 15 5-15 5V7m17 1v8m6-11v14"/>',territoire:'<path d="m3 23 9-16 7 10 6-7 6 13H3m10 0v5m11-5v5"/>',soutien:'<circle cx="9" cy="12" r="5"/><circle cx="24" cy="12" r="5"/><path d="M3 28v-3a6 6 0 0 1 12 0v3m3 0v-3a6 6 0 0 1 12 0v3"/>',communaute:'<circle cx="16" cy="16" r="12"/><path d="M4 16h24M16 4c-8 8-8 16 0 24m0-24c8 8 8 16 0 24"/>'};
const svg=(id='communaute')=>`<svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true">${icons[id]||icons.communaute}</svg>`;
const option=(id,label,note='',icon='communaute')=>({id,label,note,icon});
function steps(){const isNeed=contribution.mode==='besoin',a=contribution.answers;return[{id:'profile',title:'Vous venez en tant que…',options:[option('habitant','Habitant / public'),option('artiste','Artiste / créateur'),option('asso','Association / collectif'),option('structure','Lieu / structure'),option('partenaire','Partenaire potentiel'),option('autre','Autre regard')]},{id:'theme',title:isNeed?'Votre besoin concerne…':'Votre priorité culturelle.',options:axes.map(a=>option(a.id,a.title,'',a.id))},{id:'barriers',title:isNeed?'Quel appui recherchez-vous ?':'Qu’est-ce qui freine la participation ?',multi:true,options:isNeed?[option('lieu','Un lieu / un espace','','territoire'),option('materiel','Du matériel / des moyens','','culture'),option('reseau','Des personnes / un réseau','','soutien'),option('orientation','De l’orientation','','soutien'),option('visibilite','De la visibilité','','culture'),option('ateliers','Des ateliers / savoir-faire','','communaute')]:[option('distance','La distance / la mobilité','','territoire'),option('information','Le manque d’information','','culture'),option('horaires','Les horaires','','communaute'),option('cout','Le coût d’accès','','soutien'),option('offre','L’offre ne correspond pas','','culture'),option('aucun','Pas de frein identifié','','communaute')]},{id:'details',title:isNeed?'Ce qui ferait la différence.':'Votre territoire. Votre attente.',type:'details'},{id:'followup',title:'Rester en lien ?',type:'followup'},{id:'review',title:'Votre contribution.',type:'review'}]}
function choiceLabel(step){const a=contribution.answers[step.id];if(step.options)return (Array.isArray(a)?a:[a]).map(id=>step.options.find(o=>o.id===id)?.label).filter(Boolean).join(' · ');return ''}
function statement(){const a=contribution.answers;return `OANA — ${contribution.mode==='besoin'?'EXPRESSION D’UN BESOIN':'CONSULTATION CULTURE & TERRITOIRE'}\n\n`+steps().filter(s=>s.options).map(s=>s.title+'\n'+choiceLabel(s)).join('\n\n')+`\n\nTerritoire : ${a.town||'Non précisé'}\nAttente : ${a.detail||'Non précisée'}\nHorizon : ${a.horizon||'Non précisé'}\n\nRecontact : ${a.follow==='oui'?'Oui':'Non'}\n${a.follow==='oui'?`Nom : ${a.name||'Non indiqué'}\nEmail : ${a.email||''}\n`:''}\nIl s’agit d’une contribution qualitative, sans vote statutaire, sans promesse d’accompagnement et sans résultat collectif calculé.\nConsentement de transmission : donné par la personne lors de la préparation du dossier.`}
function renderContribution(){const list=steps();contribution.index=Math.min(contribution.index,list.length-1);const s=list[contribution.index],a=contribution.answers;let body='';if(s.options)body=`<div class="vote-options" role="group" aria-label="${s.title}">${s.options.map(o=>{const on=s.multi?(a[s.id]||[]).includes(o.id):a[s.id]===o.id;return `<button type="button" class="vote-option ${on?'chosen':''}" data-choice="${o.id}" aria-pressed="${on}">${svg(o.icon)}<span>${o.label}${o.note?`<small>${o.note}</small>`:''}</span></button>`}).join('')}</div>`;
 if(s.type==='details')body=`<div class="vote-fields"><label>Commune / territoire (facultatif)<input name="town" maxlength="100" value="${esc(a.town)}" placeholder="Ex. Rouen, Caen, une zone rurale…"></label><label>Votre attente, en quelques mots<textarea name="detail" maxlength="600" ${contribution.mode==='besoin'?'required':''} placeholder="Une situation, un manque, une idée concrète…">${esc(a.detail)}</textarea></label><label>À quel horizon ?<select name="horizon"><option value="">Choisir si vous le souhaitez</option>${['Dans les prochains mois','Cette année','À plus long terme','À définir'].map(v=>`<option ${a.horizon===v?'selected':''}>${v}</option>`).join('')}</select></label></div><p class="notice">N’indiquez pas de données sensibles ni d’informations sur une autre personne.</p>`;
 if(s.type==='followup')body=`<div class="vote-fields"><label>Souhaitez-vous être recontacté ?<select name="follow" required><option value="">Choisir</option><option value="non" ${a.follow==='non'?'selected':''}>Non, partager mon regard suffit</option><option value="oui" ${a.follow==='oui'?'selected':''}>Oui, pour échanger sur ce besoin</option></select></label><div id="contact-fields" ${a.follow==='oui'?'':'hidden'}><label>Votre nom (facultatif)<input name="name" maxlength="100" autocomplete="name" value="${esc(a.name)}"></label><label>Votre email<input name="email" type="email" maxlength="160" autocomplete="email" value="${esc(a.email)}" ${a.follow==='oui'?'required':''}></label></div><label class="consent"><input type="checkbox" name="consent" ${a.consent?'checked':''} required><span>J’accepte que cette contribution soit préparée pour OANA afin d’étudier les besoins exprimés. Le recontact n’aura lieu que si je l’ai choisi.</span></label></div><p class="notice">Aucune transmission automatique. Les réponses et coordonnées ne sont pas sauvegardées sur un serveur par cette page.</p>`;
 if(s.type==='review')body=`<div class="contribution-review">${esc(statement())}</div><p class="notice">${recipient?'Après votre vérification, transmettez la contribution à oasisnancee@gmail.com depuis votre messagerie. Votre adresse d’expédition sera visible par OANA. Vous pouvez aussi télécharger le dossier et le joindre à un email.':'La contribution est préparée sur votre appareil. Le canal de réception OANA sera ajouté après validation ; aucun dépôt collectif n’est enregistré pour le moment.'}</p><div class="dialog-actions">${recipient?'<button type="button" class="primary" id="send-contribution">Préparer l’email</button>':''}<button type="button" class="${recipient?'secondary':'primary'}" id="download-contribution">Télécharger ma contribution</button><button type="button" class="secondary" id="copy-contribution">Copier</button></div>`;
 $('#content-body').innerHTML=`<span class="eyebrow">${contribution.mode==='besoin'?'EXPRIMER UN BESOIN':'L’URNE / CONSULTATION'} · ${contribution.index+1} / ${list.length}</span><div class="vote-progress"><i style="width:${contribution.index/(list.length-1)*100}%"></i></div><h2 id="content-title" tabindex="-1">${s.title}</h2><form id="vote-form">${body}<p class="vote-status" role="status"></p><div class="vote-nav"><button type="button" class="secondary" id="vote-prev">${contribution.index?'Précédent':'Quitter'}</button>${s.type!=='review'?`<button class="primary" type="submit">${s.multi?'Valider mes choix':'Continuer'}</button>`:'<button class="secondary" type="button" id="new-contribution">Nouvelle contribution</button>'}</div></form>`;
