function draw(){if(!root.isConnected)return;root.innerHTML=`<p class="notice">Appels publics repérés pour la culture en Normandie. Une sélection ciblée, sans présomption d’éligibilité d’OANA.</p><div class="call-filters" role="group" aria-label="État des appels">${Object.entries(labels).map(([id,l])=>`<button data-filter="${id}" aria-pressed="${filter===id}">${l}</button>`).join('')}</div><p class="notice" role="status">${esc(notice)}</p><div class="calls-results">${items.filter(x=>filter==='all'||x.status===filter).map(x=>`<article class="call-card"><span class="call-status status-${x.status}">${labels[x.status]}</span><h3>${esc(x.title)}</h3><p>${esc(x.context)}</p>${x.deadline?`<p>Échéance ${x.status==='unverified'?'de référence':'annoncée'} : <strong>${date(x.deadline)}</strong></p>`:''}<small>${x.archived?'Archive vérifiée':'Vérification'} : ${new Date(x.checkedAt).toLocaleString('fr-FR')}</small>${x.status==='unverified'?'<p class="notice">La source en direct n’a pas pu confirmer l’état actuel. Consultez le règlement avant toute démarche.</p>':''}<a href="${esc(x.url)}">Source & conditions</a>${x.evidence?`<details><summary>Élément relevé automatiquement</summary><p>${esc(x.evidence)}</p></details>`:''}</article>`).join('')||'<p class="empty-call">Aucun appel avec cet état confirmé dans la sélection actuelle.</p>'}</div><div class="dialog-actions"><button class="secondary" id="calls-refresh" ${busy?'disabled':''}>Vérifier les sources</button><button class="primary" id="calls-project">Préparer une coopération</button></div><details><summary>Comment fonctionne l’actualisation ?</summary><p>À l’ouverture de cet espace, OANA consulte un service qui vérifie les échéances sur trois sources officielles sélectionnées. Les réponses sont mises en cache jusqu’à six heures. Une date reconnue permet le classement calendaire ; une source inaccessible ou un format modifié entraîne « À vérifier ». Les nouvelles opportunités hors de cette sélection et les décisions de commission nécessitent une vérification éditoriale. Les statistiques des dossiers restent des publications datées, sans extrapolation.</p><p>« En attente de commission » exige une annonce explicite de l’organisateur. Une date de clôture passée ne suffit pas. Béthencourt est conservé comme archive du règlement consulté.</p></details>`;root.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;draw()});root.querySelector('#calls-refresh').onclick=refresh;root.querySelector('#calls-project').onclick=()=>document.dispatchEvent(new CustomEvent('oana-cooperation',{detail:{}}));}
async function refresh(){if(busy)return;busy=true;notice='Vérification des sources officielles…';draw();try{const response=await fetch('/api/oana-appels',{signal:AbortSignal.timeout(12000),headers:{Accept:'application/json'}});if(!response.ok)throw Error();const data=await response.json();if(!Array.isArray(data.items)||!data.checkedAt)throw Error();const allowed=new Set(seed.map(x=>x.id));items=data.items.filter(x=>allowed.has(x.id)&&seed.find(y=>y.id===x.id).url===x.url&&Object.hasOwn(labels,x.status)).concat(closed);notice='Sources interrogées le '+new Date(data.checkedAt).toLocaleString('fr-FR')+'. Les états non confirmés restent à vérifier.'}catch{notice='Vérification en direct indisponible. Les références du 4 novembre 2026 sont conservées, sans les présenter comme des appels actuellement ouverts.';items=seed.map(x=>({...x,status:'unverified',checkedAt:'2026-11-04T00:00:00+01:00'})).concat(closed)}finally{busy=false;if(root.isConnected)draw()}}
